int main(int argc, char *argv[]) {
  (void)argc;
  (void)argv;

  auto my_mavsdk = std::make_shared<mavsdk::Mavsdk>(
      mavsdk::Mavsdk::Configuration{1, MAV_COMP_ID_ONBOARD_COMPUTER, true});
  my_mavsdk->add_any_connection("udp://127.0.0.1:14580");

  std::cout << "Waiting to discover system...\n";

  my_mavsdk->subscribe_on_new_system([my_mavsdk]() {
    std::cout << "New system discovered, calling callback...\n";

    const auto system = my_mavsdk->systems().back();
    auto my_component = std::make_shared<MyComponent>(system);
    (void)my_component;

    std::cout << "New system discovered, callback ended...\n";
  });

  while (true) {
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
  }
  return EXIT_SUCCESS;
}
```

I also logged HEARTBEAT reception, and added 3 logs in `send_autopilot_version_request`, to help debugging it :
```cpp
void SystemImpl::send_autopilot_version_request()
{
    auto prom = std::promise<MavlinkCommandSender::Result>();
    auto fut = prom.get_future();

    std::cout << "send_autopilot_version_request_async 1" << std::endl;
    send_autopilot_version_request_async(
        [&prom](MavlinkCommandSender::Result result, float) { prom.set_value(result); });

    std::cout << "send_autopilot_version_request_async 2" << std::endl;
    if (fut.get() == MavlinkCommandSender::Result::Unsupported) {
        _old_message_520_supported = false;
        LogWarn() << "Trying alternative command (512).";
        send_autopilot_version_request();
    }
    std::cout << "send_autopilot_version_request_async 3" << std::endl;
}
```

Considering above information, here is the ouput : 

```
[10:06:42|Info ] MAVSDK version: v1.4.0-765-gc9512b9f (mavsdk_impl.cpp:26)
[10:06:42|Debug] Initializing connection to remote system... (mavsdk_impl.cpp:735)
Waiting to discover system...
[10:06:43|Debug] New: System ID: 1 Comp ID: 1 (mavsdk_impl.cpp:378)
[10:06:43|Debug] Component Autopilot (1) added. (system_impl.cpp:389)
New system discovered, calling callback...
AUTOPILOT connected
New system discovered, callback ended...
HEARTBEAT RECEIVED
[10:06:44|Debug] Discovered 1 component(s) (system_impl.cpp:567)
New system discovered, calling callback...
send_autopilot_version_request_async 1
send_autopilot_version_request_async 2
[10:06:45|Warn ] Callback took more than 1 second to run.
See: https://mavsdk.mavlink.io/main/en/cpp/troubleshooting.html#user_callbacks (mavsdk_impl.cpp:852)
HEARTBEAT RECEIVED
HEARTBEAT RECEIVED
HEARTBEAT RECEIVED
```

We can see that `send_autopilot_version_request_async 3` is never reached and program still blocks. 
The only thing that confuses me is the log `AUTOPILOT connected` which is visible, and I don't understand why.

